const list=($input.first().json.list)||[];
const sku=list.filter(c=>c.advObjectType==='SKU'&&c.state!=='CAMPAIGN_STATE_ARCHIVED');
const titles={};for(const c of sku)titles[String(c.id)]={title:c.title,payment:c.PaymentType||'CPC'};
const day=$now.setZone('Europe/Moscow').minus({days:1}).toISODate();
return [{json:{body:{campaignIds:sku.map(c=>String(c.id)),dateFrom:day,dateTo:day},titles,day,campaigns:sku.length}}];

const p=$('W | Pick SKU campaigns').first().json;const r=$input.first().json||{};const src=Array.isArray(r.rows)?r.rows:[];const num=v=>{if(v===null||v===undefined||v==='')return null;const n=Number(String(v).replace(',','.'));return Number.isFinite(n)?n:null};
const rows=src.filter(v=>/^\d+$/.test(String(v.sku))&&/^\d+$/.test(String(v.campaignId))).map(v=>({tenant_id:'W',cabinet:'W',report_date:String(v.date||p.day),campaign_id:String(v.campaignId),campaign_title:(p.titles[String(v.campaignId)]||{}).title||null,payment_type:(p.titles[String(v.campaignId)]||{}).payment||'CPC',sku:String(v.sku),views:num(v.views),clicks:num(v.clicks),to_cart:num(v.toCart),orders:num(v.orders),sales:num(v.sales),expense:num(v.expense),average_cpc:num(v.avgCpc),ctr:num(v.ctr),drr:num(v.drr)}));
return [{json:{rows,row_count:rows.length,campaigns:p.campaigns,api_error:r.error?String(r.error.message||r.error):null}}];

